#!/usr/bin/env node
import fs from "node:fs";
const response = JSON.parse(fs.readFileSync(new URL("./response.json", import.meta.url), "utf8"));
const stdin = fs.readFileSync(0);
const stdout = response.stdout ?? JSON.stringify(response.results);
const stderr = response.stderr ?? "";
fs.appendFileSync(new URL("./processes.jsonl", import.meta.url), JSON.stringify({ argv: process.argv.slice(2), cwd: process.cwd(), lang: process.env.LANG, lcAll: process.env.LC_ALL, stdin: stdin.toString("base64"), stdout: Buffer.from(stdout).toString("base64"), stderr: Buffer.from(stderr).toString("base64"), status: response.status ?? 0 }) + "\n");
process.stdout.write(stdout); process.stderr.write(stderr); process.exitCode = response.status ?? 0;
